# Generated by llm-saea. See adjacent provenance JSON.
from llm_saea import Plan, benchmark, optimize

PLAN = Plan.from_dict({'surrogate': 'auto', 'operator': 'current_to_best', 'mutation': 0.55, 'crossover': 0.8, 'exploration': 0.75, 'local_fraction': 0.4, 'radius': 0.18, 'population': 30, 'generations': 5, 'reason': 'With 24 of 100 evaluations used and stagnation at 9 with zero recent improvement, the current plan is likely over-exploiting. Increasing exploration and radius encourages novelty to escape the plateau, while auto surrogate lets held-out RMSE pick RBF vs quadratic as data accumulates. current_to_best with moderate mutation/crossover balances local refinement and exploitation of the surrogate; modest population and generations keep surrogate-assisted search cheap so remaining true evaluations are spread over more iterations.'})

def solve(problem, budget=100, seed=0):
    return optimize(problem, budget=budget, seed=seed, method='saea', plan=PLAN)

if __name__ == '__main__':
    result = solve(benchmark('sphere', 5))
    print({'best_y': result.best_y, 'best_x': result.best_x.tolist()})
